		double AmbientValue( const FireProductionRemapRequest& request, bool lower,
			std::size_t component, std::size_t line )
		{
			if( !request.lineSpecificAmbientValues ) return request.ambientValues[component];
			const std::vector<double>& values=lower?request.lowerAmbientValues:
				request.upperAmbientValues;
			return values[component*request.lineCount+line];
		}

		// Smoothly transitions open-boundary ghost values between nearest interior
		// (outflow) and ambient (inflow) across a narrow 2^-24 velocity deadband.
		double ContinuousInflowValue( const double nearest, const double ambient,
			const double velocity, const bool positiveInflow, const double cellWidthM,
			const double timeStepS )
		{
			if( !(timeStepS>0.0) ) return nearest;
			const double scale=std::max(0x1p-126,std::max(std::fabs(velocity),
				std::fabs(cellWidthM/timeStepS)));
			const double width=0x1p-24*scale;
			const double signedVelocity=positiveInflow?velocity:-velocity;
			if( signedVelocity<=-width ) return nearest;
			if( signedVelocity>=width ) return ambient;
			const double weight=(signedVelocity+width)/(2.0*width);
			return nearest+weight*(ambient-nearest);
		}

		double Sample( const FireProductionRemapRequest& request,
			std::size_t component, std::size_t line, long cell )
		{
			const long count=static_cast<long>(request.lineLength);
			if( IsPeriodic(request) ) {
				long wrapped=cell%count;
				if( wrapped<0 ) wrapped+=count;
				return request.values[ValueIndex(request,component,line,
					static_cast<std::size_t>(wrapped))];
			}
			if( cell<0 ) {
				const double nearest=request.values[ValueIndex(request,component,line,0u)];
				if( LowerBoundary(request)!=FireProductionRemapPressureOpen ) return nearest;
				return ContinuousInflowValue(nearest,AmbientValue(request,true,component,line),
					request.faceVelocityMPerS[line*(request.lineLength+1u)],true,
					request.cellWidthM,request.timeStepS);
			}
			if( cell>=count ) {
				const double nearest=request.values[ValueIndex(request,component,line,
					request.lineLength-1u)];
				if( UpperBoundary(request)!=FireProductionRemapPressureOpen ) return nearest;
				return ContinuousInflowValue(nearest,AmbientValue(request,false,component,line),
					request.faceVelocityMPerS[line*(request.lineLength+1u)+request.lineLength],false,
					request.cellWidthM,request.timeStepS);
			}
			return request.values[ValueIndex(request,component,line,static_cast<std::size_t>(cell))];
		}

		// Fourth-order Colella-Woodward unlimited PPM cell edge reconstruction;
		// constant 5-cell stencils short-circuit to exact center to preserve flats.
		void UnlimitedEdges( const FireProductionRemapRequest& request,
			std::size_t component, std::size_t line, std::size_t cell,
			double& left, double& right )
		{
			const long i=static_cast<long>(cell);
			const double im2=Sample(request,component,line,i-2);
			const double im1=Sample(request,component,line,i-1);
			const double center=Sample(request,component,line,i);
			const double ip1=Sample(request,component,line,i+1);
			const double ip2=Sample(request,component,line,i+2);
			if( im2==center&&im1==center&&ip1==center&&ip2==center ) {
				left=center;right=center;return;
			}
			left=(7.0*(im1+center)-(im2+ip1))/12.0;
			right=(7.0*(center+ip1)-(im1+ip2))/12.0;
		}

		void ParabolaDeviationRange( double leftDeviation, double rightDeviation,
			double& minimum, double& maximum )
		{
			minimum=std::min(leftDeviation,rightDeviation);
			maximum=std::max(leftDeviation,rightDeviation);
			const double quadratic=3.0*(leftDeviation+rightDeviation);
			const double linear=-4.0*leftDeviation-2.0*rightDeviation;
			if( quadratic!=0.0 ) {
				const double stationary=-linear/(2.0*quadratic);
				if( stationary>0.0&&stationary<1.0 ) {
					const double value=(quadratic*stationary+linear)*stationary+leftDeviation;
					minimum=std::min(minimum,value);
					maximum=std::max(maximum,value);
				}
			}
		}

		double ContinuousSharedLimiterAlpha( const double alpha, const double headroom,
			const double signedConsumption, const double center, const double envelope )
		{
			const double scale=std::max(0x1p-126,std::max(std::fabs(center),
				std::max(std::fabs(envelope),std::fabs(signedConsumption))));
			const double width=0x1p-10*scale;
			const double numerator=headroom+std::max(0.0,-signedConsumption);
			const double denominator=std::max(signedConsumption,width);
			const double cap=std::min(1.0,numerator/denominator);
			return std::min(alpha,cap);
		}

		// Exact analytic integral of the cell PPM parabola over [beginning, end]
